// schema files (initial full state)
export function loadSchemaTables() {
  return import.meta.glob("./schema/tables/*.sql", {
    query: "?raw",
    import: "default",
    eager: true,
  });
}

/**
 * @returns {Record<string, {default: string}>}
 */
export function loadMigrations() {
  return import.meta.glob("./migrations/*.sql", {
    query: "?raw",
    import: "default",
    eager: true,
  });
}

export async function getAppliedMigrations() {
  const rows = await sql`SELECT id FROM migrations ORDER BY id`.all();
  console.log("rows geting all migraiotn applied : ", rows);
  
  return new Set(rows.map(r => r.id));
}

export async function applyMigrations(sqliteRunner) {
  // loading sql function for ease
  sql = sqliteRunner.sql.bind(sqliteRunner);
  sqlExec = sqliteRunner.sqlExec.bind(sqliteRunner);

  initMigrations();

  const migrations = loadMigrations();

  const sorted = Object.entries(migrations)
    .sort(([a], [b]) => a.localeCompare(b));

  const applied = await getAppliedMigrations();

  for (const [filename, migrationText] of sorted) {
    const id = filename.split("/").pop();

    if (applied.has(id)) continue;


    await sql`BEGIN`;

    // migration file contains raw SQL, so we must call sqlExec directly
    await sqlExec("run", migrationText, []);

    // record it
    await sql`
      INSERT INTO migrations(id)
      VALUES (${id})
    `;

    await sql`COMMIT`;
  }
}

export async function applyFullSchema(sqliteRunner) {
  const tables = loadSchemaTables();

  for (const [filename, tableSql] of Object.entries(tables)) {
    await sqliteRunner.sqlExec("run", tableSql, []); // raw full file → run directly
  }
}

